"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["89036"],{9285(e){e.exports=JSON.parse('{"tag":{"label":"sanctuary","permalink":"/docs/tags/sanctuary","allTagsPath":"/docs/tags","count":8,"items":[{"id":"sanctuary/apple","title":"Apple","description":"Apple is HALT Rescue\'s first confirmed satin carrier with osteodystrophy. He is only 8 months old and already showing signs of the painful bone disease associated with the satin coat gene.","permalink":"/docs/sanctuary/apple"},{"id":"sanctuary/gothic","title":"Gothic","description":"Gothic is Hero\'s dad \u2014 a neutered 1.5-year-old guinea pig with swollen lymph nodes that may indicate lymphoma. He is currently on antibiotics with a recheck scheduled with Dr. Ford.","permalink":"/docs/sanctuary/gothic"},{"id":"sanctuary/hero","title":"Hero","description":"Hero is a lethal white guinea pig and one of HALT Rescue\'s most beloved sanctuary residents. He\'s approaching his first birthday, loves Phillies games, and has a lot to say.","permalink":"/docs/sanctuary/hero"},{"id":"sanctuary/miles","title":"Miles","description":"Miles is a HALT Rescue sanctuary guinea pig with a more advanced case of osteodystrophy (satin syndrome). Despite his condition, he is full of joy and loves running to the side of his cage to greet visitors.","permalink":"/docs/sanctuary/miles"},{"id":"sanctuary/phoenix","title":"Phoenix","description":"Phoenix is a tiny HALT Rescue sanctuary guinea pig with stunted growth. His ultrasound and bile acid test came back normal \u2014 he is being monitored with Milk Thistle for liver support.","permalink":"/docs/sanctuary/phoenix"},{"id":"sanctuary/quill","title":"Quill","description":"Quill is a 7-year-old HALT Rescue sanctuary guinea pig celebrating his one-year anniversary with us. He came in alongside Quest, and is now the most unproblematic fella in the house.","permalink":"/docs/sanctuary/quill"},{"id":"sanctuary/sonnet","title":"Sonnet","description":"Sonnet is a HALT Rescue sanctuary guinea pig who was spayed for ovarian cysts and cervical hyperplasia. She arrived with severe hormonal hairloss and has made a remarkable recovery.","permalink":"/docs/sanctuary/sonnet"},{"id":"sanctuary/toothless","title":"Toothless","description":"Toothless is a guinea pig who arrived at HALT Rescue in April 2026 after a broken tooth created an abscess on his chin. He had emergency dental surgery and is recovering beautifully.","permalink":"/docs/sanctuary/toothless"}],"unlisted":false}}')}}]);